<div class="col-md-7"><section class="panel"><header class="panel-heading"><h4 class="panel-title">Weighted Examinations</h4></header><div class="panel-body table-responsive"><table class="table table-bordered table-hover"><thead><tr><th>Name</th><th>Session</th><th>Status</th><th>Publication</th><th>Actions</th></tr></thead><tbody><?php foreach($exams as $e):?><tr><td><?=html_escape($e['name'])?></td><td><?=html_escape($e['school_year'])?></td><td><span class="label label-<?=$e['status']==='published'?'success':($e['status']==='finalized'?'primary':'warning')?>"><?=ucfirst($e['status'])?></span></td><td><?=html_escape($e['publication_date'])?></td><td class="min-w-lg"><a class="btn btn-default btn-circle" href="<?=base_url('weighted_exam/subjects?exam_id='.$e['id'])?>" title="Configure subjects"><i class="fas fa-book"></i></a><?php if(!in_array($e['status'],['finalized','published'])):?><a class="btn btn-default btn-circle" href="<?=base_url('weighted_exam?edit='.$e['id'])?>"><i class="fas fa-pen"></i></a><?php endif?><?php if($e['status']==='finalized'):?><?=form_open('weighted_exam/status/'.$e['id'].'/published',['style'=>'display:inline'],['confirm'=>1])?><button class="btn btn-success btn-circle" title="Publish"><i class="fas fa-globe"></i></button><?=form_close()?><?=form_open('weighted_exam/status/'.$e['id'].'/active',['style'=>'display:inline'],['confirm'=>1])?><button class="btn btn-warning btn-circle" title="Reopen" onclick="return confirm('Reopen finalized results for authorized corrections?')"><i class="fas fa-lock-open"></i></button><?=form_close()?><?php elseif($e['status']==='published'):?><?=form_open('weighted_exam/status/'.$e['id'].'/draft',['style'=>'display:inline'],['confirm'=>1])?><button class="btn btn-warning btn-circle" title="Authorized reopen" onclick="return confirm('Reopen published results? They will no longer be published.')"><i class="fas fa-lock-open"></i></button><?=form_close()?><?php elseif($e['status']==='draft'):?><?=form_open('weighted_exam/delete/'.$e['id'],['style'=>'display:inline'],['confirm'=>1])?><button class="btn btn-danger btn-circle" onclick="return confirm('Delete this draft and all its weighted exam data?')"><i class="fas fa-trash"></i></button><?=form_close()?><?php endif?></td></tr><?php endforeach?></tbody></table></div></section></div></div>

